package com.bank.dsa;

import java.math.BigDecimal;
import java.util.logging.*;

// Runnable demo: charge the higher of two fee quotes.
public class LargerOfTwoDemo {
    private static final Logger log = Logger.getLogger(LargerOfTwoDemo.class.getName());

    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        Logger root = Logger.getLogger("");
        for (Handler old : root.getHandlers()) root.removeHandler(old);
        root.addHandler(h);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        FeeSelector selector = new FeeSelector();

        BigDecimal standard = new BigDecimal("12.00");  // A
        BigDecimal promo    = new BigDecimal("9.00");   // B
        BigDecimal charged  = selector.higherFee(standard, promo);
        log.info(() -> "Rajesh SAV2001: applying higher fee Rs." + charged);
    }
}

// ─── Would be in FeeSelector.java in a real project ───
class FeeSelector {
    // Return the larger amount. compareTo (NOT equals) compares numeric value, ignoring scale.
    BigDecimal higherFee(BigDecimal a, BigDecimal b) {
        if (a == null || b == null) {
            throw new IllegalArgumentException("Fee quotes must not be null");
        }
        if (a.compareTo(b) > 0) {   // decision: A > B ?
            return a;               // Yes branch
        } else {
            return b;               // No branch (also covers A == B)
        }
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
